import mechanize
from bs4 import BeautifulSoup


def task_func(url, form_id, data):
    try:
        browser = mechanize.Browser()
        browser.set_handle_robots(False)
        browser.set_handle_refresh(False)

        browser.open(url)

        target_id = str(form_id)

        def _match_form(form):
            form_id_attr = str(form.attrs.get("id", ""))
            form_name_attr = str(form.attrs.get("name", ""))
            return form_id_attr == target_id or form_name_attr == target_id

        browser.select_form(predicate=_match_form)
        form = browser.form

        if data:
            for key, value in data.items():
                try:
                    # Try the straightforward assignment first.
                    form[key] = value
                except Exception:
                    # Fallback for multi-value controls.
                    try:
                        if isinstance(value, (list, tuple)):
                            form[key] = [str(v) for v in value]
                        else:
                            form[key] = str(value)
                    except Exception:
                        pass

        response = browser.submit()
        html = response.read()
        soup = BeautifulSoup(html, "html.parser")

        if soup.title:
            title = soup.title.get_text(strip=True)
            if title:
                return title

        return "No Title"
    except Exception:
        return "No Title"
